import {PAD_DEFAULTS,PAD_LABELS,PAD_BUTTONS,gamepadPreferences,controllerFamily} from './gamepad-preferences.js';
export function setupGamepadBindings(settings,{save,apply},root=document){
 const fields=new Map(),node=id=>root.getElementById(id),make=(tag)=>root.createElement(tag);
 for(const [action,title]of Object.entries(PAD_LABELS)){const label=make('label'),text=make('span'),select=make('select');label.className='gamepad-binding';text.textContent=title;select.setAttribute('aria-label','Controller '+title);for(const [value,name]of [[-1,'UNBOUND'],...PAD_BUTTONS.map((name,i)=>[i,name])]){const option=make('option');option.value=String(value);option.textContent=name;select.append(option);}label.append(text,select);node('gamepad-bindings').append(label);fields.set(action,select);select.addEventListener('change',()=>{const value=Number(select.value),old=settings.gamepad.buttons[action],other=Object.keys(PAD_LABELS).find(key=>key!==action&&value>=0&&settings.gamepad.buttons[key]===value);if(other)settings.gamepad.buttons[other]=old;settings.gamepad.buttons[action]=value;sync();apply();save();node('settings-status').textContent=other?'Controller buttons swapped.':'Controller binding saved.';});}
 for(const key of ['steerAxis','pitchAxis','lookX','lookY'])node('pad-'+key).addEventListener('change',()=>{settings.gamepad[key]=Number(node('pad-'+key).value);apply();save();});
 for(const key of ['invertSteering','invertLookY'])node('pad-'+key).addEventListener('change',()=>{settings.gamepad[key]=node('pad-'+key).checked;apply();save();});
 node('reset-gamepad').addEventListener('click',()=>{settings.gamepad=gamepadPreferences();sync();apply();save();node('settings-status').textContent='Controller defaults restored.';});
 function sync(){for(const [action,select]of fields)select.value=String(settings.gamepad.buttons[action]);for(const key of ['steerAxis','pitchAxis','lookX','lookY'])node('pad-'+key).value=String(settings.gamepad[key]);for(const key of ['invertSteering','invertLookY'])node('pad-'+key).checked=settings.gamepad[key];}sync();return {sync};
}

// Controller navigation acts on the current dialog only. Native selects/ranges
// are changed explicitly because untrusted synthetic arrow events cannot open them.
export class ControllerUI{
 constructor({playing=()=>false,back=()=>{},consume=()=>{},root=document}={}){Object.assign(this,{playing,back,consume,root});this.previous=[];this.nextMove=0;this.family='STANDARD GAMEPAD';this.keyboardTarget=null;this.shift=false;this.buildKeyboard();}
 buildKeyboard(){const root=this.root,keys=root.getElementById('controller-keys');for(const value of 'qwertyuiopasdfghjklzxcvbnm1234567890.,!?\'_-'){const button=root.createElement('button');button.type='button';button.textContent=value;button.addEventListener('click',()=>this.type(value));keys.append(button);}for(const [id,fn]of [['controller-newline',()=>this.type('\n')],['controller-space',()=>this.type(' ')],['controller-delete',()=>this.type(null)],['controller-case',()=>{this.shift=!this.shift;root.getElementById('controller-case').textContent=this.shift?'SHIFT ON':'SHIFT';}],['controller-done',()=>this.finishKeyboard(true)],['controller-cancel',()=>this.finishKeyboard(false)]])root.getElementById(id).addEventListener('click',fn);root.getElementById('controller-keyboard').addEventListener('cancel',event=>{event.preventDefault();this.finishKeyboard(false);});}
 type(char){const input=this.root.getElementById('controller-text');if(char===null)input.value=[...input.value].slice(0,-1).join('');else if([...input.value].length<input.maxLength)input.value+=this.shift?char.toUpperCase():char;input.dispatchEvent(new Event('input',{bubbles:true}));}
 openKeyboard(target){this.keyboardTarget=target;const input=this.root.getElementById('controller-text');input.value=target.value||'';input.maxLength=target.maxLength>0?target.maxLength:160;this.root.getElementById('controller-newline').hidden=target.tagName!=='TEXTAREA';this.root.getElementById('controller-keyboard').showModal();this.root.getElementById('controller-keys').querySelector('button')?.focus();}
 finishKeyboard(commit){const target=this.keyboardTarget;this.keyboardTarget=null;if(commit&&target){target.value=this.root.getElementById('controller-text').value;target.dispatchEvent(new Event('input',{bubbles:true}));target.dispatchEvent(new Event('change',{bubbles:true}));}this.root.getElementById('controller-keyboard').close();target?.focus();}
 visible(element){return !element.disabled&&!element.closest('[hidden]')&&element.getClientRects().length>0;}
 items(scope){return [...scope.querySelectorAll('button,input,select,textarea,a[href],[tabindex="0"]')].filter(element=>this.visible(element)&&element.tabIndex!==-1);}
 move(items,direction){const current=this.root.activeElement;if(!items.includes(current)){items[0]?.focus();return;}if(current.dataset.settingsTab&&['left','right'].includes(direction)){const tabs=[...this.root.querySelectorAll('[data-settings-tab]')],index=tabs.indexOf(current),next=tabs[(index+(direction==='right'?1:-1)+tabs.length)%tabs.length];next?.click();next?.focus();return;}if(current.tagName==='SELECT'&&['left','right'].includes(direction)){const options=[...current.options].filter(option=>!option.disabled),index=options.findIndex(option=>option.value===current.value),next=(index+(direction==='right'?1:-1)+options.length)%options.length;current.value=options[next].value;current.dispatchEvent(new Event('change',{bubbles:true}));return;}if(current.type==='range'&&['left','right'].includes(direction)){current.value=String(Math.max(Number(current.min),Math.min(Number(current.max),Number(current.value)+(direction==='right'?1:-1)*(Number(current.step)||1))));current.dispatchEvent(new Event('input',{bubbles:true}));current.dispatchEvent(new Event('change',{bubbles:true}));return;}const box=current.getBoundingClientRect(),x=box.x+box.width/2,y=box.y+box.height/2,candidates=items.filter(item=>item!==current).map(item=>{const rect=item.getBoundingClientRect(),dx=rect.x+rect.width/2-x,dy=rect.y+rect.height/2-y,along=direction==='left'?-dx:direction==='right'?dx:direction==='up'?-dy:dy,cross=['left','right'].includes(direction)?Math.abs(dy):Math.abs(dx);return {item,along,score:along+cross*3};}).filter(entry=>entry.along>3).sort((a,b)=>a.score-b.score);const next=candidates[0]?.item||items[(items.indexOf(current)+(['up','left'].includes(direction)?-1:1)+items.length)%items.length];next?.focus();next?.scrollIntoView?.({block:'nearest'});}
 accept(){const current=this.root.activeElement;if(!current)return;if(current.tagName==='SELECT'){this.move([current],'right');return;}if(current.tagName==='INPUT'&&['text','search'].includes(current.type)||current.tagName==='TEXTAREA'){this.openKeyboard(current);return;}if(current.tagName==='INPUT'&&current.type==='checkbox'){current.checked=!current.checked;current.dispatchEvent(new Event('change',{bubbles:true}));return;}current.click?.();}
 update(now){let pad;try{pad=Array.from(navigator.getGamepads?.()||[]).find(p=>p?.connected);}catch{return;}if(!pad){this.previous=[];this.root.body.classList.remove('using-controller');this.root.getElementById('controller-hint').hidden=true;return;}this.family=controllerFamily(pad.id);const buttons=pad.buttons.map(button=>button?.value>.5),edge=id=>buttons[id]&&!this.previous[id],dialogs=[...this.root.querySelectorAll('dialog[open]')],modal=this.root.getElementById('controller-keyboard').open?this.root.getElementById('controller-keyboard'):(this.root.activeElement?.closest('dialog[open]')||dialogs.at(-1)),active=!!modal||!this.playing();if(active){this.root.body.classList.add('using-controller');const scope=modal||this.root.getElementById('lobby'),items=this.items(scope);if(!items.includes(this.root.activeElement))items[0]?.focus();const x=pad.axes[0]||0,y=pad.axes[1]||0,direction=buttons[12]||y<-.55?'up':buttons[13]||y>.55?'down':buttons[14]||x<-.55?'left':buttons[15]||x>.55?'right':null;if(direction&&now>=this.nextMove){this.move(items,direction);this.nextMove=now+(this.lastDirection===direction?130:300);this.lastDirection=direction;}if(!direction){this.nextMove=0;this.lastDirection=null;}if(edge(0)){this.accept();this.consume([0]);}if(edge(1)||edge(9)){if(modal){const event=new Event('cancel',{cancelable:true});modal.dispatchEvent(event);if(!event.defaultPrevented)modal.close();}else this.back();this.consume([edge(1)?1:9]);}}this.previous=buttons;const hint=this.root.getElementById('controller-hint');hint.hidden=false;hint.textContent=this.family+' · '+(this.family==='PLAYSTATION'?'CROSS SELECT · CIRCLE BACK':'A SELECT · B BACK')+' · D-PAD / LEFT STICK NAVIGATE';}
}
